actions.script:
import groovy.json.JsonOutput
// everything below comes from the guard config in Setup: entities, fields, and which are switched off
def guards = ec.entity.find("moqui.basic.Enumeration").condition("enumTypeId", "ConfigApprovalField").disableAuthz().useCache(false).list().findAll { it.optionValue != "N" }
entityList = guards.collect { it.enumCode.substring(0, it.enumCode.lastIndexOf(".")) }.unique().sort().collect { [entityName: it, label: it.substring(it.lastIndexOf(".") + 1)] }
changeTypeList = [[changeType: "Update", label: "Change a guarded field"], [changeType: "Create", label: "Add a record"], [changeType: "Delete", label: "Delete a record"]]
fieldList = []; recordList = []; pkNames = []; fieldHint = ""
if (entityName && ec.entity.isEntityDefined(entityName) && guards.any { it.enumCode.startsWith(entityName + ".") }) {
    def ed = ec.entity.getEntityDefinition(entityName)
    pkNames = ed.getPkFieldNames()
    fieldList = guards.findAll { it.enumCode.startsWith(entityName + ".") }.collect {
        String f = it.enumCode.substring(entityName.length() + 1)
        [fieldName: f, label: "${it.description ?: f} (${f}, ${ed.getFieldInfo(f)?.type ?: ''})".toString()] }
    fieldHint = ed.getAllFieldNames().join(", ")
    if (changeType == "Update" || changeType == "Delete") {
        recordList = ec.entity.find(entityName).orderBy(pkNames as List).limit(300).list().collect { r ->
            [recordKey: JsonOutput.toJson(pkNames.collectEntries { [(it): r.get(it)?.toString()] }), label: pkNames.collect { r.get(it) }.join(" / ")] }
    }
} else { entityName = null }
